public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;
    for (String str : strings) {
        for (int i = 0; i < str.length(); i++) {
            for (int j = i + 1; j <= str.length(); j++) {
                String subStr = str.substring(i, j);
                String reverseSubStr = new StringBuilder(subStr).reverse().toString();
                if (anyStringContains(subStr, strings) || anyStringContains(reverseSubStr, strings)) {
                    maxLength = Math.max(maxLength, subStr.length());
                }
            }
        }
    }
    return maxLength;
}

private boolean anyStringContains(String subStr, List<String> strings) {
    for (String str : strings) {
        if (str.contains(subStr)) {
            return true;
        }
    }
    return false;
}
