public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n];
    return dfs(start[0], end[0], visited, paths) ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int current, int target, boolean[] visited, int[][] paths) {
    if (current == target) {
        return true;
    }
    visited[current] = true;
    for (int[] path : paths) {
        if ((path[0] == current && !visited[path[1]]) || (path[1] == current && !visited[path[0]])) {
            if (dfs(path[0] == current ? path[1] : path[0], target, visited, paths)) {
                return true;
            }
        }
    }
    return false;
}
