public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[paths.length];
    for (int i = 0; i < paths.length; i++) {
        if (Arrays.equals(paths[i], start)) {
            boolean result = dfs(paths, visited, i, end);
            if (result) {
                return "can be travelled";
            }
        }
    }
    return "cannot be travelled";
}

private static boolean dfs(int[][] paths, boolean[] visited, int current, int[] end) {
    if (Arrays.equals(paths[current], end)) {
        return true;
    }
    visited[current] = true;
    for (int i = 0; i < paths.length; i++) {
        if (!visited[i] && (Arrays.equals(paths[i], paths[current]) || Arrays.equals(paths[i], paths[current + 1]))) {
            boolean result = dfs(paths, visited, i, end);
            if (result) {
                return true;
            }
        }
    }
    visited[current] = false;
    return false;
}
