public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n];
    boolean[] reachable = new boolean[n];
    int startIndex = start[0] * n + start[1];
    int endIndex = end[0] * n + end[1];
    dfs(startIndex, paths, visited, reachable);
    return reachable[endIndex] ? "can be travelled" : "cannot be travelled";
}

private static void dfs(int currentNode, int[][] paths, boolean[] visited, boolean[] reachable) {
    if (visited[currentNode]) return;
    visited[currentNode] = true;
    reachable[currentNode] = true;
    for (int path : paths[currentNode]) {
        dfs(path, paths, visited, reachable);
    }
}
