public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];

    if (!isValidPath(start, end, paths)) {
        return "cannot be travelled";
    }

    if (dfs(start[0], start[1], end[0], end[1], visited, paths)) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

private static boolean isValidPath(int[] start, int[] end, int[][] paths) {
    return Math.abs(start[0] - end[0]) + Math.abs(start[1] - end[1]) == 1;
}

private static boolean dfs(int x, int y, int endX, int endY, boolean[][] visited, int[][] paths) {
    if (x == endX && y == endY) {
        return true;
    }

    visited[x][y] = true;

    int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    for (int[] direction : directions) {
        int newX = x + direction[0];
        int newY = y + direction[1];

        if (newX >= 0 && newX < paths.length && newY >= 0 && newY < paths[0].length && !visited[newX][newY] && isValidPath(new int[]{x, y}, new int[]{newX, newY}, paths)) {
            if (dfs(newX, newY, endX, endY, visited, paths)) {
                return true;
            }
        }
    }

    visited[x][y] = false;
    return false;
}
