public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n];
    boolean[] from = new boolean[n];
    for (int[] path : paths) {
        visited[path[0]] = true;
        visited[path[1]] = true;
    }
    for (int[] path : paths) {
        if (path[0] == start[0] && path[1] == start[1]) {
            from[path[1]] = true;
        }
        if (path[1] == start[0] && path[0] == start[1]) {
            from[path[0]] = true;
        }
    }
    for (int[] path : paths) {
        if (from[path[0]] && visited[path[1]] && path[1] == end[0] && path[0] == end[1]) {
            return "can be travelled";
        }
        if (from[path[1]] && visited[path[0]] && path[0] == end[0] && path[1] == end[1]) {
            return "can be travelled";
        }
    }
    return "cannot be travelled";
}
