public static String appx(String word1, String word2) {
    Set<Character> set1 = new HashSet<>();
    for (char c : word1.toCharArray()) {
        set1.add(c);
    }
    int commonCount = 0;
    for (char c : word2.toCharArray()) {
        if (set1.contains(c)) {
            commonCount++;
            set1.remove(c);
        }
    }
    int approximateValue = commonCount * 2 + 1;
    int denominator = word1.length() + word2.length();
    for (int i = 2; i <= denominator; i++) {
        while (approximateValue % i == 0 && denominator % i == 0) {
            approximateValue /= i;
            denominator /= i;
        }
    }
    return "appx(" + word1 + ", " + word2 + ") = " + approximateValue + "/" + denominator;
}

