public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        adj.add(new ArrayList<>());
    }
    for (int[] e : edges) {
        adj.get(e[0]).add(e[1]);
        adj.get(e[1]).add(e[0]);
    }
    return dfs(0, -1, adj, hasApple) * 2;
}

private int dfs(int node, int parent, List<List<Integer>> adj, boolean[] hasApple) {
    int time = 0;
    for (int neighbor : adj.get(node)) {
        if (neighbor == parent) continue;
        int childTime = dfs(neighbor, node, adj, hasApple);
        if (childTime > 0 || hasApple[neighbor]) {
            time += childTime + 2;
        }
    }
    return time;
}
