}

private int[] dfs(List<List<Integer>> graph, boolean[] hasApple, int node, boolean[] visited) {
    visited[node] = true;
    int time = 0;
    for (int neighbor : graph.get(node)) {
        if (!visited[neighbor]) {
            int[] result = dfs(graph, hasApple, neighbor, visited);
            if (result[1] || hasApple[neighbor]) {
                time += result[0] + 2;
            }
        }
    }
    return new int[]{time, hasApple[node]};
}
