public boolean hasAllCodes(String s, int k) {
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int bitmask = 0;
    int n = s.length();

    for (int i = 0; i < n; i++) {
        bitmask = (bitmask << 1) & (total - 1);
        bitmask |= s.charAt(i) - '0';

        if (i >= k - 1) {
            seen[bitmask] = true;
        }
    }

    for (boolean b : seen) {
        if (!b) {
            return false;
        }
    }

    return true;
}
