    fib[0] = 1;
    fib[1] = 1;
    for (int i = 2; i < 30; i++) {
        fib[i] = fib[i - 1] + fib[i - 2];
    }
    int count = 0;
    for (int i = 29; i >= 0; i--) {
        if (k >= fib[i]) {
            k -= fib[i];
            count++;
        }
        if (k == 0) {
            break;
        }
    }
    return count;
}
