import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    Queue<Integer> queue = new LinkedList<>();
    for (int i = 0; i < 10; i++) {
        queue.offer(i);
        if (i >= low && i <= high) {
            result.add(i);
        }
    }
    while (!queue.isEmpty()) {
        int num = queue.poll();
        int lastDigit = num % 10;
        if (lastDigit > 0) {
            int nextNum = num * 10 + lastDigit - 1;
            if (nextNum <= high) {
                queue.offer(nextNum);
                if (nextNum >= low) {
                    result.add(nextNum);
                }
            }
        }
        if (lastDigit < 9) {
            int nextNum = num * 10 + lastDigit + 1;
            if (nextNum <= high) {
                queue.offer(nextNum);
                if (nextNum >= low) {
                    result.add(nextNum);
                }
            }
        }
    }
    return result;
}
