        int lastDigit = current % 10;
        if (lastDigit > 0) {
            int next = current * 10 + lastDigit - 1;
            if (next <= high) {
                result.add(next);
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            int next = current * 10 + lastDigit + 1;
            if (next <= high) {
                result.add(next);
                queue.offer(next);
            }
        }
    }

    return result;
