import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;

public class SteppingNumbers {
    public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low <= 0 && 0 <= high) result.add(0);
        for (int i = 1; i <= 9; i++) {
            bfs(low, high, i, result);
        }
        result.sort(Integer::compareTo);
        return result;
    }

    private static void bfs(int low, int high, int num, List<Integer> result) {
        LinkedList<Integer> queue = new LinkedList<>();
        queue.add(num);
        while (!queue.isEmpty()) {
            num = queue.poll();
            if (num > high) continue;
            if (num >= low) result.add(num);
            int lastDigit = num % 10;
            if (lastDigit != 0) queue.add(num * 10 + lastDigit - 1);
            if (lastDigit != 9) queue.add(num * 10 + lastDigit + 1);
        }
    }
}
