public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    // Arrays to store the lengths of consecutive 1s
    int[] horizontal = new int[n];
    int[] vertical = new int[m];
    int[] diagonal = new int[n];
    int[] antiDiagonal = new int[n];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Horizontal
                horizontal[j]++;
                // Vertical
                vertical[i]++;
                // Diagonal
                diagonal[j]++;
                // Anti-diagonal
                antiDiagonal[j - i + n - 1]++;

                maxLength = Math.max(maxLength, horizontal[j]);
                maxLength = Math.max(maxLength, vertical[i]);
                maxLength = Math.max(maxLength, diagonal[j]);
                maxLength = Math.max(maxLength, antiDiagonal[j - i + n - 1]);
            } else {
                // Reset counts if the current cell is 0
                horizontal[j] = 0;
                vertical[i] = 0;
                diagonal[j] = 0;
                antiDiagonal[j - i + n - 1] = 0;
            }
        }
    }

    return maxLength;
}
