public static int squarePermutations(int[] A) {
    if (A.length == 0) return 1;
    boolean[] visited = new boolean[A.length];
    return backtrack(A, 0, visited);
}

private static int backtrack(int[] A, int index, boolean[] visited) {
    if (index == A.length - 1) return 1;
    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (!visited[i] && isPerfectSquare(A[index] + A[i])) {
            visited[i] = true;
            count += backtrack(A, index + 1, visited);
            visited[i] = false;
        }
    }
    return count;
}

private static boolean isPerfectSquare(int num) {
    int root = (int) Math.sqrt(num);
    return root * root == num;
}
