private static int backtrack(int[] A, int index, int count) {
    if (index == A.length - 1) {
        return 1;
    }
    int result = 0;
    for (int i = index + 1; i < A.length; i++) {
        if (isPerfectSquare(A[index] + A[i])) {
            swap(A, index + 1, i);
            result += backtrack(A, index + 1, count + 1);
            swap(A, index + 1, i);
        }
    }
    return result;
}

private static void swap(int[] A, int i, int j) {
