public static int squarePermutations(int[] A) {
    int n = A.length;
    int[][] dp = new int[n][1 << n];
    for (int i = 0; i < n; i++) {
        dp[i][1 << i] = 1;
    }
    for (int mask = 1; mask < (1 << n); mask++) {
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) != 0) {
                for (int j = 0; j < n; j++) {
                    if ((mask & (1 << j)) == 0 && isPerfectSquare(A[i] + A[j])) {
                        dp[i][mask | (1 << j)] += dp[j][mask];
                    }
                }
            }
        }
    }
    int result = 0;
    for (int i = 0; i < n; i++) {
        result += dp[i][(1 << n) - 1];
    }
    return result;
}

private static boolean isPerfectSquare(int x) {
    int sqrt = (int) Math.sqrt(x);
    return sqrt * sqrt == x;
}
