private static void backtrack(List<String> result, char[] half, int start, int n) {
    if (start * 2 >= n) {
        String s = new String(half);
        if (n % 2 == 0) {
            result.add(s + new StringBuilder(s).reverse().toString());
        } else {
            for (char c : new char[]{'0', '1', '8'}) {
                result.add(s + c + new StringBuilder(s).reverse().toString());
            }
        }
        return;
    }
    for (char c : new char[]{'0', '1', '6', '8', '9'}) {
        if (start == 0 && c == '0') continue;
        half[start] = c;
        if (c == '6' || c == '9') half[n - start - 1] = c == '6' ? '9' : '6';
        else half[n - start - 1] = c;
        backtrack(result, half, start + 1, n);
    }
}
