        if (left == right) {
            if (current.length() == 0 || current.charAt(0) != '0') {
                result.add(current.append('0').toString());
                current.deleteCharAt(current.length() - 1);
                result.add(current.append('1').toString());
                current.deleteCharAt(current.length() - 1);
                result.add(current.append('8').toString());
                current.deleteCharAt(current.length() - 1);
            }
            return;
        }
        if (left > 0) {
            current.append('0');
            helper(result, current, left + 1, right);
            current.deleteCharAt(current.length() - 1);
        }
        current.append('1');
        helper(result, current, left + 1, right);
        current.deleteCharAt(current.length() - 1);
        current.append('6');
        helper(result, current, left + 1, right);
        current.deleteCharAt(current.length() - 1);
        current.append('8');
        helper(result, current, left + 1, right);
        current.deleteCharAt(current.length() - 1);
        current.append('9');
        helper(result, current, left + 1, right);
        current.deleteCharAt(current.length() - 1);
    }

    public static void main(String[] args) {
        System.out.println(centerSymmetricNumbers(2)); // Output: ["11","69","88","96"]
        System.out.println(centerSymmetricNumbers(1)); // Output: ["0","1","8"]
    }
}
