public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= 9; i++) {
        if (i > n) break;
        lexicalOrderHelper(result, i, n);
    }
    return result;
}

private static void lexicalOrderHelper(List<Integer> result, int current, int n) {
    if (current > n) return;
    result.add(current);
    for (int i = 0; i <= 9; i++) {
        int next = current * 10 + i;
        if (next > n) break;
        lexicalOrderHelper(result, next, n);
    }
}
